import { Router } from 'express';
import { z } from 'zod';
import { requireUser } from '../auth';

export const ordersRouter = Router();

const NewOrder = z.object({ sku: z.string(), quantity: z.number().int().positive() });

ordersRouter.post('/orders', requireUser, async (req, res) => {
  const parsed = NewOrder.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: 'invalid order' });
  const order = await createOrder({ userId: req.user.id, ...parsed.data });
  return res.status(201).json(order);
});

import request from 'supertest';
import { app } from '../server/app';

test('rejects an order without a quantity', async () => {
  const response = await request(app).post('/orders').send({ sku: 'A-1' });
  expect(response.status).toBe(400);
});
